using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Emotes are the plainest possible verb: no dice, no HP, no inventory, no
/// condition flags, nothing left behind except one event and two lines of
/// text. They exist for a person with nowhere left to go and nothing left to
/// solve who still wants to do something other than walk or talk.
/// </summary>
public class EmoteTests
{
    [Fact]
    public void SittingTellsTheActorAndTheRoom()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");
        var (_, bobOut) = WorldFixture.Join(engine, "Bob");

        engine.HandleInput(alice, "sit");

        Assert.Contains("You sit down.", aliceOut.Text);
        Assert.Contains("Alice sits down.", bobOut.Text);
        Assert.Contains(events.Events, e => e.Type == EventType.Emote && e.Payload["emote"] == "sit");
    }

    [Fact]
    public void EmotingChangesNothingAboutTheCharacter()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var before = (alice.Character.HitPoints, alice.Character.Inventory.Count,
            alice.Character.Conditions.Count);

        engine.HandleInput(alice, "laugh");
        engine.HandleInput(alice, "sit");
        engine.HandleInput(alice, "stand");

        var after = (alice.Character.HitPoints, alice.Character.Inventory.Count,
            alice.Character.Conditions.Count);
        Assert.Equal(before, after);
    }

    [Fact]
    public void ASoloCharacterCanStillEmoteWithNoOneToHearIt()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "wave");

        Assert.Contains("You wave.", aliceOut.Text);
        Assert.Contains(events.Events, e => e.Type == EventType.Emote && e.Payload["emote"] == "wave");
    }
}

